TEST(ResourceAddressedExecutionKernelTest, ZeroSpeedHoldTimeoutEndsTheOperationStoppedWithoutError) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  ResourceAddressedExecutionKernel kernel(
      {registration(
          make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
  const auto operation = kernel.execute(motion_operation("request.zero-hold"));
  ASSERT_TRUE(operation.ok()) << operation.error().message;
  engine.emit_transition(ExecutionState::kValidating, ExecutionState::kExecuting);

  // An unrelated stop request event is not a hold timeout.
  engine.deliver_event(KernelEvent{KernelEventType::kStopRequested,
                                   engine.next_execution_id,
                                   0,
                                   ExecutionState::kExecuting,
                                   ExecutionState::kExecuting,
                                   std::nullopt,
                                   {{"reason", "something_else"}}});
  EXPECT_FALSE(
      kernel.get_operation_state(operation.value().operation_id).value().active_stop_id.has_value());

  const KernelEvent hold{KernelEventType::kStopRequested,
                         engine.next_execution_id,
                         0,
                         ExecutionState::kExecuting,
                         ExecutionState::kExecuting,
                         std::nullopt,
                         {{"reason", "zero_speed_hold_timeout"}}};
  engine.deliver_event(hold);
  std::optional<StopId> stop_id;
  ASSERT_TRUE(wait_until([&] {
    const auto state = kernel.get_operation_state(operation.value().operation_id);
    if (!state.ok() || !state.value().active_stop_id.has_value()) return false;
    stop_id = state.value().active_stop_id;
    const auto status = kernel.get_stop_status(*stop_id);
    return status.ok() && status.value().stop_certificate.has_value();
  }));
  engine.deliver_event(hold);
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 1);
  ASSERT_TRUE(engine.last_stop_stage.has_value());
  EXPECT_EQ(engine.last_stop_stage->stage_index,
            engine.last_stop_stage->participant_stop_plan.stage_commands.size() - 1U);
  const auto state = kernel.get_operation_state(operation.value().operation_id);
  ASSERT_TRUE(state.ok());
  EXPECT_EQ(state.value().state, OperationStateKind::kStopped);
  EXPECT_EQ(state.value().participants.front().state, OperationStateKind::kStopped);
  EXPECT_FALSE(state.value().participants.front().terminal_error.has_value());
  EXPECT_EQ(state.value().active_stop_id, stop_id);
  EXPECT_FALSE(kernel.get_stop_fault_latch().has_value());
  // Q31: recorded as the hold-timeout Stop it requested, never an escalation.
  const auto status = kernel.get_stop_status(*stop_id);
  ASSERT_TRUE(status.ok());
  const auto certificate =
      kernel.get_stop_certificate(status.value().stop_certificate->stop_certificate_id);
  ASSERT_TRUE(certificate.ok());
  EXPECT_EQ(certificate.value().result, StopCertificateResultDTO::kSucceededNominal);
  ASSERT_EQ(certificate.value().lane_hard_stop_requested.size(), 1U);
}

// Q18 on the current backends: a Stop ramp that the controller finished
// outside its goal tolerance is `main`'s confirmed-but-not-settled case. The
// participant ends InterventionRequired and no second Stop command is issued.
TEST(ResourceAddressedExecutionKernelTest,
     StopRampOutsideGoalToleranceEndsInterventionRequiredWithoutASecondStopCommand) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.next_stop_result = StopResultDTO{
      false, ErrorDTO{"motion_interrupt_backend_stop_failed",
                      "managed FJT terminal soft-stop goal failed: goal tolerance violated",
                      {{"reason", "stop_goal_tolerance_violated"},
                       {"controller_result_code", "-5"}}}};
  ResourceAddressedExecutionKernel kernel(
      {registration(
          make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
  const auto operation = kernel.execute(motion_operation("request.goal-tolerance"));
  ASSERT_TRUE(operation.ok()) << operation.error().message;
  engine.emit_transition(ExecutionState::kValidating, ExecutionState::kExecuting);
  const auto stopped =
      kernel.stop(stop_request("request.goal-tolerance.stop", operation.value(), 1U));
  ASSERT_TRUE(stopped.ok()) << stopped.error().message;
  ASSERT_TRUE(wait_until([&] {
    const auto status = kernel.get_stop_status(stopped.value().stop_id);
    return status.ok() && status.value().stop_certificate.has_value();
  }));
  EXPECT_EQ(engine.translate_stop_stage_calls.load(), 1);
  ASSERT_TRUE(engine.last_stop_stage.has_value());
  EXPECT_EQ(engine.last_stop_stage->stage_index, 0U);
  const auto state = kernel.get_operation_state(operation.value().operation_id);
  ASSERT_TRUE(state.ok());
  EXPECT_EQ(state.value().state, OperationStateKind::kInterventionRequired);
  const auto& participant = state.value().participants.front();
  EXPECT_EQ(participant.state, OperationStateKind::kInterventionRequired);
  ASSERT_TRUE(participant.terminal_error.has_value());
  EXPECT_EQ(participant.terminal_error->details.at("reason"), "stop_goal_tolerance_violated");
  EXPECT_EQ(participant.terminal_error->details.at("emergency_fallback"),
            "not_attempted_controlled_stop_already_confirmed");
  EXPECT_EQ(participant.terminal_error->details.at("hard_stop_transitioned"), "false");
  // Q29: no cell-wide Stop-fault latch (as `main`).
  EXPECT_FALSE(kernel.get_stop_fault_latch().has_value());
}

// Q33: a hard stop the Stop planner chose as the right Stop ends Stopped with
// no error (main's ros2_control operator path); a hard stop used as a
// fallback after a failed soft Stop keeps the degraded-Stop error.
TEST(ResourceAddressedExecutionKernelTest,
     PlannerSelectedHardStopEndsStoppedWithoutTheDegradedStopError) {
  for (const bool planner_selected : {true, false}) {
    SCOPED_TRACE(planner_selected ? "planner-selected hard stop" : "fallback hard stop");
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    std::map<std::string, std::string> details{{"reason", "soft_on_path_infeasible"},
                                               {"recommended_disposition", "hard_stop"}};
    if (planner_selected) details.emplace("stop_disposition", "planner_selected_hard_stop");
    engine.next_stop_result = StopResultDTO{
        false, ErrorDTO{"motion_interrupt_backend_stop_failed", "soft Stop infeasible", details}};
    engine.translate_stop_stage_hook = [&, calls = std::make_shared<unsigned>(0U)] {
      if ((*calls)++ > 0U) engine.next_stop_result = StopResultDTO{true, std::nullopt};
    };
    ResourceAddressedExecutionKernel kernel(
        {registration(
            make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
            engine)},
        clock, scheduler, default_journal,
        {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
    const auto operation = kernel.execute(motion_operation("request.planner-hard"));
    ASSERT_TRUE(operation.ok()) << operation.error().message;
    engine.emit_transition(ExecutionState::kValidating, ExecutionState::kExecuting);
    const auto stopped =
        kernel.stop(stop_request("request.planner-hard.stop", operation.value(), 1U));
    ASSERT_TRUE(stopped.ok()) << stopped.error().message;
    ASSERT_TRUE(wait_until([&] {
      const auto status = kernel.get_stop_status(stopped.value().stop_id);
      return status.ok() && status.value().stop_certificate.has_value();
    }));
    EXPECT_EQ(engine.translate_stop_stage_calls.load(), 2);
    const auto state = kernel.get_operation_state(operation.value().operation_id);
    ASSERT_TRUE(state.ok());
    EXPECT_EQ(state.value().state, OperationStateKind::kStopped);
    const auto& participant = state.value().participants.front();
    EXPECT_EQ(participant.state, OperationStateKind::kStopped);
    EXPECT_EQ(participant.terminal_error.has_value(), !planner_selected);
    const auto status = kernel.get_stop_status(stopped.value().stop_id);
    ASSERT_TRUE(status.ok()) << status.error().message;
    const auto certificate =
        kernel.get_stop_certificate(status.value().stop_certificate->stop_certificate_id);
    ASSERT_TRUE(certificate.ok()) << certificate.error().message;
    EXPECT_EQ(certificate.value().result, planner_selected
                                              ? StopCertificateResultDTO::kSucceededNominal
                                              : StopCertificateResultDTO::kSucceededEscalated);
    if (!planner_selected) {
      EXPECT_EQ(participant.terminal_error->details.at("emergency_fallback"),
                "legacy_stop_succeeded");
    }
    EXPECT_FALSE(kernel.get_stop_fault_latch().has_value());
  }
}


// =============================================================================
// Core robot participant over IExecutionPort as the participant's Stop-stage
// port behind the real addressed Kernel (shared execution design §4.2, §7.7).
// A scripted stock-JTC stand-in drives the fake port: one controller cycle per
// millisecond of fake time. Until a test starts a Stop it runs on its own
// thread; from then on it runs in lockstep with the participant's Stop-stage
// waits (one cycle per wait), so the Stop's logical timing never depends on
// host scheduling.
// =============================================================================

using JtcPort = manyforge::core::testing::FakeExecutionPort;

/// The participant's Stop-stage waiter. Unbound, a wait is a short real sleep
/// (the controller cycles on its own thread). Bound to a controller, each wait
/// is exactly one controller cycle and takes no real time.
class StopStageWaits final {
 public:
  void Wait() {
    {
      std::lock_guard lock(mutex_);
      if (cycle_) {
        cycle_();
        return;
      }
    }
    std::this_thread::sleep_for(std::chrono::microseconds(200));
  }
  void Bind(std::function<void()> cycle) {
    std::lock_guard lock(mutex_);
    cycle_ = std::move(cycle);
  }
  /// Returns once no bound cycle is running.
  void Unbind() {
    std::lock_guard lock(mutex_);
    cycle_ = nullptr;
  }

 private:
  std::mutex mutex_;
  std::function<void()> cycle_;
};

class ScriptedJtc final {
 public:
  struct Script {
    /// Cycles from a replacement's start until it reports kSucceeded; the
    /// success hold (cursor 0, reference velocity 0) follows (SX-162/164).
    int replacement_cycles{40};
    /// Cycles of cancel braking before the reference reaches zero.
    int cancel_cycles{20};
  };

  ScriptedJtc(JtcPort& port, FakeClock& clock, std::shared_ptr<StopStageWaits> waits,
              Script script)
      : port_(port), clock_(clock), waits_(std::move(waits)), script_(script),
        thread_([this](std::stop_token stop) { Run(stop); }) {}
  ~ScriptedJtc() {
    waits_->Unbind();
    thread_.request_stop();
    thread_.join();
  }

  [[nodiscard]] std::vector<JtcPort::Command> commands() const {
    return port_.commands();
  }

  /// The speed factor the controller applies from now on (its own report).
  void SetAppliedFactor(double factor) { factor_ = factor; }

  /// Call before requesting the Stop: fake time stops at the latest sample,
  /// and from then on each participant Stop-stage wait is exactly one
  /// controller cycle. The Stop's sample-to-dispatch age and every later Stop
  /// timing are then protocol facts, not host-scheduling artefacts.
  void CycleOnStopStageWaits() {
    {
      std::lock_guard lock(cycle_mutex_);
      lockstep_ = true;
    }
    waits_->Bind([this] {
      std::lock_guard lock(cycle_mutex_);
      Cycle();
    });
  }

 private:
  void Sample(double cursor, double position, double velocity) {
    ExecutionControllerSampleDTO sample;
    sample.source_stamp_ns = clock_.now();
    sample.local_receipt_stamp_ns = clock_.now();
    sample.local_receipt_count = ExecutionReceiptCount(++receipts_);
    sample.binding_epoch = ExecutionBindingEpoch(1U);
    sample.cursor_s = cursor;
    sample.applied_factor = factor_.load();
    sample.reference_positions_rad = {position};
    sample.reference_velocities_rad_s = {velocity};
    sample.reference_accelerations_rad_s2 = {0.0};
    sample.command_positions_rad = {position};
    sample.measured_positions_rad = {position};
    sample.measured_velocities_rad_s = std::vector<double>{velocity};
    sample.error_positions_rad = {0.0};
    port_.SetSample(sample);
  }

  void Executing(const ExecutionGoalKey& key) {
    ExecutionGoalObservationDTO goal;
    goal.key = key;
    goal.binding_epoch = ExecutionBindingEpoch(1U);
    goal.phase = ExecutionGoalPhase::kExecuting;
    goal.mechanism_goal_id =
        MechanismGoalId("uuid-" + std::to_string(key.controller_goal_generation.value()));
    ExecutionGoalFeedbackDTO feedback;
    feedback.source_stamp_ns = clock_.now();
    feedback.local_receipt_stamp_ns = clock_.now();
    goal.latest_feedback = feedback;
    port_.SetGoal(goal);
  }

  void Run(const std::stop_token& stop) {
    while (!stop.stop_requested()) {
      std::this_thread::sleep_for(std::chrono::microseconds(200));
      std::lock_guard lock(cycle_mutex_);
      if (!lockstep_) Cycle();
    }
  }

  /// One controller cycle: one millisecond of fake time, the commands received
  /// since the last cycle, then this cycle's report.
  void Cycle() {
    clock_.advance(1'000'000);
    const auto commands = port_.commands();
    for (; seen_ < commands.size(); ++seen_) {
      const auto& command = commands[seen_];
      if (const auto* submit = std::get_if<JtcPort::SubmitCall>(&command)) {
        Executing(submit->key);
        active_ = submit->key;
        mode_ = Mode::kOriginal;
        cycle_ = 0;
      } else if (const auto* replace =
                     std::get_if<JtcPort::ReplaceCall>(&command)) {
        if (!port_.ReadGoal(replace->next_key)) continue;  // refused, not registered
        Executing(replace->next_key);
        port_.FinishGoal(replace->active_key, ExecutionGoalResult::kPreemptedBy,
                         replace->next_key, clock_.now());
        active_ = replace->next_key;
        mode_ = Mode::kReplacement;
        replacement_end_ = replace->trajectory.waypoints.back().positions_rad.front();
        cycle_ = 0;
      } else if (const auto* cancel =
                     std::get_if<JtcPort::CancelCall>(&command)) {
        port_.MarkCancelSent(cancel->key, clock_.now());
        if (active_ && cancel->key == *active_) {
          mode_ = Mode::kCancel;
          cycle_ = 0;
        }
      }
    }
    if (!active_) return;
    ++cycle_;
    switch (mode_) {
      case Mode::kOriginal:
        cursor_ += 0.001 * factor_.load();
        Sample(cursor_, 0.5 * cursor_, 0.5 * factor_.load());
        break;
      case Mode::kReplacement:
        if (cycle_ < script_.replacement_cycles) {
          Sample(0.001 * cycle_, 0.5 * cursor_, 0.2);
        } else if (cycle_ == script_.replacement_cycles) {
          port_.FinishGoal(*active_, ExecutionGoalResult::kSucceeded, std::nullopt,
                           clock_.now());
        } else {
          Sample(0.0, replacement_end_, 0.0);  // success hold at the trajectory's end
        }
        break;
      case Mode::kCancel:
        if (factor_.load() == 0.0) {
          // At factor 0 the cancel trajectory cannot advance (Q35): JTC
          // keeps reporting its frozen state and acknowledges the cancel.
          Sample(cursor_, 0.5 * cursor_, 0.0);
          if (cycle_ == 2) {
            port_.AcknowledgeCancel(*active_, clock_.now());
            port_.FinishGoal(*active_, ExecutionGoalResult::kCanceled, std::nullopt,
                             clock_.now());
          }
          break;
        }
        if (cycle_ <= script_.cancel_cycles) {
          Sample(0.001 * cycle_, 0.5 * cursor_,
                 0.5 * (1.0 - static_cast<double>(cycle_) / script_.cancel_cycles));
        }
        if (cycle_ == script_.cancel_cycles + 1) {
          port_.AcknowledgeCancel(*active_, clock_.now());
          port_.FinishGoal(*active_, ExecutionGoalResult::kCanceled, std::nullopt,
                           clock_.now());
        }
        break;
    }
  }

  enum class Mode { kOriginal, kReplacement, kCancel };
  JtcPort& port_;
  FakeClock& clock_;
  std::shared_ptr<StopStageWaits> waits_;
  Script script_;
  /// Serializes cycles; set, the own thread no longer cycles (lockstep).
  std::mutex cycle_mutex_;
  bool lockstep_{false};
  std::size_t seen_{0U};
  std::optional<ExecutionGoalKey> active_;
  Mode mode_{Mode::kOriginal};
  int cycle_{0};
  double cursor_{0.0};
  double replacement_end_{0.0};
  std::atomic<double> factor_{1.0};
  std::uint64_t receipts_{0U};
  std::jthread thread_;
};

/// The addressed Kernel with one arm whose Stop-stage port is the Core
/// participant over a fake port; the fake engine prepares and dispatches the
/// Kernel-minted participant through the same Core participant.
/// The stage outcomes of a certificate, for diagnostics.
std::string StageReasons(const StopCertificateDTO& certificate) {
  std::string text;
  for (const auto& attempt : certificate.attempted_stage_results) {
    text += "[stage " + std::to_string(attempt.result.request.stage_index) + " outcome " +
            std::to_string(static_cast<int>(attempt.result.outcome));
    if (attempt.result.error) {
      for (const auto& [key, value] : attempt.result.error->details) text += " " + key + "=" + value;
    }
    text += "]";
  }
  return text;
}

struct PortParticipantCell {
  explicit PortParticipantCell(bool controlled_hard_stop = true,
                               bool operator_profile = true) {
    ExecutionLaneFactsDTO facts;
    facts.joint_names = {"mf2_joint_1"};
    facts.supports_scale = true;
    facts.has_measured_velocity = true;
    facts.state_rate_hz = 1000.0;
    facts.controller_update_rate_hz = 1000.0;
    port->SetLaneFacts(facts);
    ExecutionPortParticipantConfig config;
    config.stop.trip_authority = StateAuthorityClass::kCommanded;
    config.stop.stop_traj_delta_s = 0.05;
    config.stop.sample_period_s = 0.01;
    config.stop.replacement_start_allowance_s = 0.02;
    if (controlled_hard_stop) config.stop.max_deceleration_on_cancel_rad_s2 = {{"mf2_joint_1", 4.0}};
    config.stop.hard_stop_completion_timeout_ns = 1'000'000'000;
    config.late_cycle_margin_s = 0.015;
    participant = std::make_unique<ExecutionPortParticipant>(
        binding, port, clock, scheduler,
        [waits = waits](TimePoint, const std::stop_token&) { waits->Wait(); },
        ExecutionPortParticipantStateAuthority{&publication, [] { return Result<void>::Ok(); }},
        std::move(config));
    TrajectoryDTO trajectory;
    for (int index = 0; index <= 16; ++index) {
      const double t = 0.25 * index;
      const double v = index == 0 || index == 16 ? 0.0 : 0.5;
      trajectory.waypoints.push_back({t, {0.5 * t}, {v}, {0.0}});
    }
    trajectory.runtime_scale_bounds = TrajectoryRuntimeScaleBoundsDTO{4.0, 16.0};
    engine.prepared_trajectory = std::move(trajectory);
    engine.execution_backend = participant.get();
    auto arm = registration(binding, engine, false, {}, true);
    arm.stop_execution_port = participant.get();
    if (!operator_profile) arm.default_operator_stop_profile.reset();
    kernel = std::make_unique<ResourceAddressedExecutionKernel>(
        std::vector<RuntimeParticipantExecutionRegistration>{arm}, clock, scheduler, journal,
        ResourceAddressedExecutionKernelConfig{RequestOwnerEpoch("kernel.epoch.1"),
                                               CellId("cell.test"), 8U});
  }

  /// Executes one motion and waits until the controller samples it.
  OperationAcceptedDTO Execute(const std::string& request_id) {
    const auto operation = kernel->execute(motion_operation(request_id));
    if (!operation.ok()) throw std::logic_error(operation.error().message);
    engine.emit_transition(ExecutionState::kValidating, ExecutionState::kExecuting);
    if (!wait_until([&] {
          const auto sample = port->ReadSample();
          return sample.has_value() && sample->cursor_s > 0.3;
        })) {
      throw std::logic_error("the controller never executed the dispatched goal");
    }
    return operation.value();
  }

  std::uint64_t Revision(const OperationAcceptedDTO& operation) const {
    return kernel->get_operation_state(operation.operation_id).value().operation_revision.value();
  }

  StopStatusDTO WaitForCertificate(const StopId& stop_id) const {
    std::optional<StopStatusDTO> status;
    if (!wait_until(
            [&] {
              auto current = kernel->get_stop_status(stop_id);
              if (!current.ok()) return false;
              status = std::move(current.value());
              return status->stop_certificate.has_value();
            },
            std::chrono::seconds(10))) {
      throw std::logic_error("Stop did not certify");
    }
    return *status;
  }

  template <typename Call>
  std::vector<Call> Calls() const {
    std::vector<Call> calls;
    for (const auto& command : port->commands()) {
      if (const auto* call = std::get_if<Call>(&command)) calls.push_back(*call);
    }
    return calls;
  }

  RuntimeParticipantBinding binding =
      make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  FakeClock clock;
  ManualScheduler scheduler;
  FakeOperationJournal journal;
  std::shared_ptr<JtcPort> port =
      std::make_shared<JtcPort>();
  std::shared_ptr<StopStageWaits> waits = std::make_shared<StopStageWaits>();
  ObservedRobotStatePublication publication{
      {"mf2_joint_1"},
      {ObservedRobotStateSourceConfig{ObservedRobotStateSourceKind::kJointState, "fixture_jtc",
                                      ObservedRobotStateAuthorityProfile::kCommandedSimulation, 0}}};
  FakeParticipantEngine engine;
  std::unique_ptr<ExecutionPortParticipant> participant;
  std::unique_ptr<ResourceAddressedExecutionKernel> kernel;
};

TEST(ResourceAddressedExecutionKernelTest, PortParticipantSoftStopCertifiesThroughTheReplacement) {
  PortParticipantCell cell;
  ScriptedJtc jtc(*cell.port, cell.clock, cell.waits, {});
  const auto operation = cell.Execute("request.port.soft.execute");
  jtc.CycleOnStopStageWaits();
  const auto stopped = cell.kernel->stop(stop_request("request.port.soft.stop", operation, cell.Revision(operation)));
  ASSERT_TRUE(stopped.ok()) << stopped.error().message;
  const auto status = cell.WaitForCertificate(stopped.value().stop_id);
  EXPECT_EQ(status.state, StopStatusStateDTO::kSucceeded);
  const auto certificate =
      cell.kernel->get_stop_certificate(status.stop_certificate->stop_certificate_id);
  ASSERT_TRUE(certificate.ok());
  EXPECT_EQ(certificate.value().result, StopCertificateResultDTO::kSucceededNominal)
      << StageReasons(certificate.value());
  ASSERT_EQ(certificate.value().attempted_stage_results.size(), 1U);
  EXPECT_EQ(certificate.value().attempted_stage_results.front().result.actual_provider_contract_mode,
            MotionControlledStopMode::kSoftOnPath);
  EXPECT_EQ(cell.Calls<JtcPort::ReplaceCall>().size(), 1U);
  EXPECT_TRUE(cell.Calls<JtcPort::CancelCall>().empty());
  const auto terminal = cell.kernel->get_operation_state(operation.operation_id);
  ASSERT_TRUE(terminal.ok());
  EXPECT_EQ(terminal.value().state, OperationStateKind::kStopped);
  EXPECT_FALSE(terminal.value().participants.front().terminal_error.has_value());
  EXPECT_FALSE(cell.kernel->get_stop_fault_latch().has_value());
}

TEST(ResourceAddressedExecutionKernelTest,
     PortParticipantFailedSoftStopEscalatesToTheControlledHardStopOrTheCancel) {
  for (const bool controlled_hard_stop : {true, false}) {
    SCOPED_TRACE(controlled_hard_stop ? "level 3" : "level 4");
    PortParticipantCell cell(controlled_hard_stop);
    ScriptedJtc jtc(*cell.port, cell.clock, cell.waits, {});
    const auto operation = cell.Execute("request.port.hard.execute");
    // The controller refuses the soft Stop replacement: the Kernel escalates.
    cell.port->QueueCommandResult({ExecutionPortDispatch::kNotDispatched,
                                   ExecutionPortRefusal::kInvalidInput, std::nullopt});
    jtc.CycleOnStopStageWaits();
    const auto stopped = cell.kernel->stop(stop_request("request.port.hard.stop", operation, cell.Revision(operation)));
    ASSERT_TRUE(stopped.ok()) << stopped.error().message;
    const auto status = cell.WaitForCertificate(stopped.value().stop_id);
    const auto certificate =
        cell.kernel->get_stop_certificate(status.stop_certificate->stop_certificate_id);
    ASSERT_TRUE(certificate.ok());
    EXPECT_EQ(certificate.value().result, StopCertificateResultDTO::kSucceededEscalated)
        << StageReasons(certificate.value());
    const auto& stages = certificate.value().attempted_stage_results;
    ASSERT_EQ(stages.size(), 2U);
    EXPECT_EQ(stages.back().result.outcome, ParticipantStopStageOutcomeDTO::kSucceeded);
    const auto& evidence =
        std::get<JsonObjectDTO>(stages.back().result.evidence_items.front().evidence->value);
    EXPECT_EQ(std::get<std::string>(evidence.at("hard_stop_level").value),
              controlled_hard_stop ? "controlled_hard_stop" : "jtc_cancel_decelerate_on_cancel");
    EXPECT_EQ(cell.Calls<JtcPort::CancelCall>().empty(), controlled_hard_stop);
    // Item 25 / Q33: a fallback hard stop ends Stopped with the degraded-Stop
    // error and no cell-wide latch.
    const auto terminal = cell.kernel->get_operation_state(operation.operation_id);
    ASSERT_TRUE(terminal.ok());
    EXPECT_EQ(terminal.value().state, OperationStateKind::kStopped);
    EXPECT_TRUE(terminal.value().participants.front().terminal_error.has_value());
    EXPECT_FALSE(cell.kernel->get_stop_fault_latch().has_value());
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     PortParticipantResetWhileBusyRunsTheOperatorProfileElseTheHardStop) {
  for (const bool operator_profile : {true, false}) {
    SCOPED_TRACE(operator_profile ? "operator profile" : "no operator profile");
    PortParticipantCell cell(true, operator_profile);
    ScriptedJtc jtc(*cell.port, cell.clock, cell.waits, {});
    const auto operation = cell.Execute("request.port.reset.execute");
    jtc.CycleOnStopStageWaits();
    ASSERT_TRUE(cell.kernel->reset(control_request("request.port.reset", operation, cell.Revision(operation))).ok());
    ASSERT_TRUE(wait_until([&] { return cell.engine.certified_reset_calls.load() == 1; },
                           std::chrono::seconds(10)));
    // Q27: the operator profile's soft Stop first (a replacement through the
    // participant), else the lane's hard stop (level 3 here); no cancel.
    const auto replaces = cell.Calls<JtcPort::ReplaceCall>();
    ASSERT_EQ(replaces.size(), 1U);
    EXPECT_TRUE(cell.Calls<JtcPort::CancelCall>().empty());
    const auto stop = cell.kernel->get_stop_status(StopId("stop.kernel.epoch.1.1"));
    ASSERT_TRUE(stop.ok());
    ASSERT_TRUE(stop.value().stop_certificate.has_value());
    const auto certificate =
        cell.kernel->get_stop_certificate(stop.value().stop_certificate->stop_certificate_id);
    ASSERT_TRUE(certificate.ok());
    EXPECT_EQ(certificate.value().result, StopCertificateResultDTO::kSucceededNominal)
        << StageReasons(certificate.value());
    EXPECT_FALSE(cell.kernel->get_stop_fault_latch().has_value());
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     PortParticipantStopAtAppliedFactorZeroIsThePlainCancelWithoutError) {
  // Q45: JTC reports an applied factor of exactly 0 at the Stop request: the
  // Stop is the plain cancel, finished on factor 0 plus the positive cancel
  // acknowledgement (Q35), and the motion ends Stopped with no error.
  PortParticipantCell cell;
  ScriptedJtc jtc(*cell.port, cell.clock, cell.waits, {});
  const auto operation = cell.Execute("request.port.zero.execute");
  jtc.SetAppliedFactor(0.0);
  ASSERT_TRUE(wait_until([&] {
    const auto sample = cell.port->ReadSample();
    return sample.has_value() && sample->applied_factor == 0.0;
  }));
  jtc.CycleOnStopStageWaits();
  const auto stopped = cell.kernel->stop(
      stop_request("request.port.zero.stop", operation, cell.Revision(operation)));
  ASSERT_TRUE(stopped.ok()) << stopped.error().message;
  const auto status = cell.WaitForCertificate(stopped.value().stop_id);
  EXPECT_EQ(status.state, StopStatusStateDTO::kSucceeded);
  const auto certificate =
      cell.kernel->get_stop_certificate(status.stop_certificate->stop_certificate_id);
  ASSERT_TRUE(certificate.ok());
  EXPECT_EQ(certificate.value().result, StopCertificateResultDTO::kSucceededNominal)
      << StageReasons(certificate.value());
  const auto& stages = certificate.value().attempted_stage_results;
  ASSERT_EQ(stages.size(), 2U);
  EXPECT_EQ(stages.front().result.attempt_disposition,
            StopStageAttemptDispositionDTO::kNotDispatched);
  EXPECT_EQ(stages.front().result.error->details.at("stop_disposition"),
            "applied_factor_zero_hard_stop");
  const auto& evidence =
      std::get<JsonObjectDTO>(stages.back().result.evidence_items.front().evidence->value);
  EXPECT_EQ(std::get<std::string>(evidence.at("hard_stop_level").value),
            "jtc_cancel_decelerate_on_cancel");
  EXPECT_EQ(std::get<std::string>(
                std::get<JsonObjectDTO>(evidence.at("post_command_sample").value)
                    .at("finish_basis")
                    .value),
            "factor_zero_cancel_acknowledged");
  EXPECT_TRUE(cell.Calls<JtcPort::ReplaceCall>().empty());
  EXPECT_EQ(cell.Calls<JtcPort::CancelCall>().size(), 1U);
  const auto terminal = cell.kernel->get_operation_state(operation.operation_id);
  ASSERT_TRUE(terminal.ok());
  EXPECT_EQ(terminal.value().state, OperationStateKind::kStopped);
  EXPECT_FALSE(terminal.value().participants.front().terminal_error.has_value());
  EXPECT_FALSE(cell.kernel->get_stop_fault_latch().has_value());
}

TEST(ResourceAddressedExecutionKernelTest,
     PortParticipantStopDuringARampDownFollowsTheFrozenFactorStop) {
  // Q45 applies only to an applied 0: while the controller still applies a
  // non-zero factor (the ramp-down to the last sent 0 in progress) the Stop is
  // the normal frozen-factor Stop. Frozen at 0 it cannot be planned, so the
  // hard-stop fallback ends Stopped with the degraded-Stop error (Q33).
  PortParticipantCell cell;
  cell.participant->set_runtime_velocity_scale(0.0);  // last value sent: 0
  ScriptedJtc jtc(*cell.port, cell.clock, cell.waits, {});
  const auto operation = cell.Execute("request.port.ramp.execute");
  jtc.SetAppliedFactor(0.2);
  ASSERT_TRUE(wait_until([&] {
    const auto sample = cell.port->ReadSample();
    return sample.has_value() && sample->applied_factor == 0.2;
  }));
  jtc.CycleOnStopStageWaits();
  const auto stopped = cell.kernel->stop(
      stop_request("request.port.ramp.stop", operation, cell.Revision(operation)));
  ASSERT_TRUE(stopped.ok()) << stopped.error().message;
  const auto status = cell.WaitForCertificate(stopped.value().stop_id);
  const auto certificate =
      cell.kernel->get_stop_certificate(status.stop_certificate->stop_certificate_id);
  ASSERT_TRUE(certificate.ok());
  EXPECT_EQ(certificate.value().result, StopCertificateResultDTO::kSucceededEscalated)
      << StageReasons(certificate.value());
  const auto& stages = certificate.value().attempted_stage_results;
  ASSERT_EQ(stages.size(), 2U);
  EXPECT_EQ(stages.front().result.error->details.at("reason"),
            "controlled_stop_frozen_factor_unusable");
  const auto terminal = cell.kernel->get_operation_state(operation.operation_id);
  ASSERT_TRUE(terminal.ok());
  EXPECT_EQ(terminal.value().state, OperationStateKind::kStopped);
  const auto& error = terminal.value().participants.front().terminal_error;
  ASSERT_TRUE(error.has_value());
  EXPECT_EQ(error->details.at("controlled_stop_error_reason"),
            "controlled_stop_frozen_factor_unusable");
}

#ifdef MANYFORGE_TEST_SQLITE_OPERATION_JOURNAL
TEST(ResourceAddressedExecutionKernelTest,
     ConfigurationApplyConvergenceUsesTheExistingDurableOwnerAndKeepsOldClaimsUntilSuccess) {
  TemporaryOperationJournal temporary;
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  SqliteOperationJournal journal(temporary.directory / "operation.sqlite3", CellId("cell.test"),
                                 32U);
  ResourceAddressedExecutionKernelConfig config{RequestOwnerEpoch("kernel.epoch.1"),
                                                CellId("cell.test"), 16U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  config.cell_admission_settlement_validator = [](const auto&, const auto&) {
    return Result<void>::Ok();
  };
  ResourceAddressedExecutionKernel kernel(
      {registration(
          make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, journal, std::move(config));
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  const CellAdmissionClaimIntentDTO old_intent{CellAdmissionClaimKindDTO::kManagerApply,
                                               CellAdmissionOwnerRoleDTO::kManager,
                                               EmptyManagerLivenessSet().manager_owner_epoch,
                                               "old.apply",
                                               RequestId("old.apply"),
                                               ContentDigest(test_digest('1')),
                                               kernel.GetAuthoringAdmission().admission_generation,
                                               {},
                                               {},
                                               {}};
  const auto old = kernel.AcquireCellAdmissionClaim(old_intent);
  ASSERT_TRUE(old.ok()) << old.error().message;
  CellAdmissionReadinessSnapshotDTO incomplete{
      true,
      ProgramCycleStatusDTO{RequestOwnerEpoch("program.owner"),
                            1U,
                            ProgramCycleStateDTO::kIdleAfterReset,
                            {},
                            {},
                            {}},
      true,
      1U,
      0U,
      true,
      false,
      0U,
      1U,
      1U};
  ASSERT_TRUE(kernel.UpdateCellAdmissionReadiness(incomplete).ok());
  auto fresh_intent = old_intent;
  fresh_intent.owner_transaction_id = "fresh.apply";
  fresh_intent.request_id = RequestId("fresh.apply");
  fresh_intent.expected_admission_generation = kernel.GetAuthoringAdmission().admission_generation;
  EXPECT_FALSE(kernel.AcquireCellAdmissionClaim(fresh_intent).ok());
  EXPECT_FALSE(kernel.AcquireConfigurationApplyCellAdmissionClaim(fresh_intent, {}).ok());
  const auto unknown = kernel.AcquireConfigurationApplyCellAdmissionClaim(
      fresh_intent, [](const auto&, auto, const auto&, const auto&) {
        return Result<void>::Err(
            {"actual_installed_state_unknown", "actual state is unavailable", {}});
      });
  ASSERT_FALSE(unknown.ok());
  EXPECT_EQ(unknown.error().code, "actual_installed_state_unknown");
  EXPECT_EQ(kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kManagerApply),
            old.value());
  int checked = 0;
  const auto fresh = kernel.AcquireConfigurationApplyCellAdmissionClaim(
      fresh_intent, [&](const auto& intent, auto held, const auto&, const auto& epoch) {
        ++checked;
        EXPECT_EQ(intent, fresh_intent);
        EXPECT_EQ(held.size(), 1U);
        if (!held.empty()) {
          EXPECT_EQ(held.front(), old.value());
        }
        EXPECT_EQ(epoch, EmptyManagerLivenessSet().manager_runtime_epoch);
        return Result<void>::Ok();
      });
  ASSERT_TRUE(fresh.ok()) << fresh.error().message;
  const auto replay = kernel.AcquireConfigurationApplyCellAdmissionClaim(
      fresh_intent, [&](const auto&, auto, const auto&, const auto&) {
        ++checked;
        return Result<void>::Err(
            {"unexpected_revalidation", "replay must retain original acquisition", {}});
      });
  ASSERT_TRUE(replay.ok());
  EXPECT_EQ(replay.value(), fresh.value());
  EXPECT_EQ(checked, 1);
  EXPECT_EQ(kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kManagerApply,
                                              old_intent.owner_transaction_id),
            old.value());
  EXPECT_EQ(kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kManagerApply,
                                              fresh_intent.owner_transaction_id),
            fresh.value());
  EXPECT_FALSE(
      kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kManagerApply, "foreign.apply")
          .has_value());
  EXPECT_EQ(kernel.ReadHeldCellAdmissionClaims(CellAdmissionClaimKindDTO::kManagerApply),
            (std::vector{old.value(), fresh.value()}));
  const auto& claim = fresh.value();
  const CellAdmissionClaimReleaseDTO success{
      claim.intent.owner_role,
      claim.intent.owner_epoch,
      claim.intent.owner_transaction_id,
      claim.intent.request_id,
      claim.intent.request_payload_digest,
      claim.acquired_admission_generation,
      claim.claim_generation,
      {CellAdmissionSettlementKindDTO::kTerminalEffectsSettled, ContentDigest(test_digest('2'))}};
  const auto before_fences = kernel.ReleaseTerminalApplyClaimsAfterSuccess(
      claim, success, [](const auto&, const auto&, auto) {
        return Result<void>::Err({"old_fence_held", "old fence has not been released", {}});
      });
  ASSERT_FALSE(before_fences.ok());
  EXPECT_EQ(before_fences.error().code, "old_fence_held");
  const auto accounted = kernel.ReleaseTerminalApplyClaimsAfterSuccess(
      claim, success, [&](const auto& actual, const auto& release, auto old_rows) {
        EXPECT_EQ(actual, claim);
        EXPECT_EQ(release, success);
        EXPECT_EQ(old_rows.size(), 1U);
        if (!old_rows.empty()) {
          EXPECT_EQ(old_rows.front(), old.value());
        }
        return Result<void>::Ok();
      });
  ASSERT_TRUE(accounted.ok()) << accounted.error().message;
  EXPECT_FALSE(accounted.value().authoring_allowed);  // Fresh exclusion is still held.
  EXPECT_FALSE(kernel
                   .ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kManagerApply,
                                               old_intent.owner_transaction_id)
                   .has_value());
  EXPECT_EQ(kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kManagerApply,
                                              fresh_intent.owner_transaction_id),
            fresh.value());
  EXPECT_EQ(kernel.ReadHeldCellAdmissionClaims(CellAdmissionClaimKindDTO::kManagerApply),
            (std::vector{fresh.value()}));
  ASSERT_TRUE(kernel.ReleaseCellAdmissionClaim(success).ok());
  EXPECT_TRUE(kernel.ReadHeldCellAdmissionClaims(CellAdmissionClaimKindDTO::kManagerApply).empty());
  ASSERT_TRUE(ready_cell_admission(kernel).ok());
  EXPECT_TRUE(kernel.GetAuthoringAdmission().authoring_allowed);
  EXPECT_EQ(engine.execute_calls, 0);
}
#endif


TEST(ResourceAddressedExecutionKernelTest, OrdinaryPrepareFailureAndStopWaitForTheSameBlockedWriter) {
  using namespace std::chrono_literals;
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine arm;
  arm.defer_prepare_completion = true;
  FinalPneumaticTestBackend backend;
  GripperParticipantEngine output(backend, clock);
  HeldSettlementCall prepare, writer;
  PreparedGripperForwarder forwarder(output, [] {});
  forwarder.prepare_hook = prepare.Blocker();
  std::promise<void> actual_prepare_returned;
  forwarder.after_prepare_hook = [&] { actual_prepare_returned.set_value(); };
  FakeOperationJournal journal;
  journal.record_hook = [block = writer.Blocker()](std::string_view kind) {
    if (kind == "state:coordinated_participant_prepared_waiting") block();
  };
  const ProgramCommandSchemaRefDTO schema{CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto moving = make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  const auto command = coordinated_occurrence(make_binding("gripper", "gripper.target", "tool.gripper.command",
      CoordinateKind::kLinear, schema), "2");
  auto ordinary = LogicalGripperRegistration(command, output);
  ordinary.prepared_motion_engine = &forwarder;
  ResourceAddressedExecutionKernel kernel({registration(moving, arm), ordinary}, clock, scheduler, journal,
      {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
  auto executing = std::async(std::launch::async, [&] {
    return kernel.execute(coordinated_motion_command_operation("failure.waiting.writer"));
  });
  ASSERT_TRUE(prepare.Entered());
  auto prepared_motion = std::async(std::launch::async, [&] { return arm.complete_preparation(); });
  ASSERT_TRUE(writer.Entered());
  backend.refuse_validation = true;
  prepare.Release();
  ASSERT_EQ(actual_prepare_returned.get_future().wait_for(10s), std::future_status::ready);
  // The owner has returned a real refusal while the operation's writer is
  // occupied. Stop is accepted before that writer is allowed to return.
  // This observes the external ordering, not a private mutex waiter count.
  EXPECT_EQ(executing.wait_for(10ms), std::future_status::timeout);
  const auto stopped = kernel.full_stop({{RequestId("failure.waiting.writer.stop"),
      RequestOwnerEpoch("kernel.epoch.1"), "test", {}}, StopGeneration(0U), {}});
  ASSERT_TRUE(stopped.ok());
  EXPECT_EQ(backend.commands, 0);
  writer.Release();
  ASSERT_TRUE(prepared_motion.get().ok());
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(wait_until([&] {
    const auto reconciled = kernel.reconcile_subordinate_state();
    const auto state = kernel.get_operation_state(accepted.value().operation_id);
    return reconciled.ok() && state.ok() &&
        state.value().participants.back().state == OperationStateKind::kInterventionRequired;
  }));
  ASSERT_TRUE(wait_until([&] {
    return kernel.get_stop_status(stopped.value().stop_id).value().stop_certificate.has_value();
  }));
  const auto state = kernel.get_operation_state(accepted.value().operation_id).value();
  ASSERT_TRUE(state.participants.back().terminal_error);
  EXPECT_EQ(state.participants.back().terminal_error->code, "actual_prepare_refused");
  EXPECT_EQ(state.participants.front().state, OperationStateKind::kStopped);
  EXPECT_EQ(state.active_stop_id, stopped.value().stop_id);
  for (const auto& slot : kernel.resource_snapshot()) {
    ASSERT_TRUE(slot.owner);
    EXPECT_EQ(slot.state, ResourceSlotState::kTerminal);
    EXPECT_EQ(slot.owner->operation_id, accepted.value().operation_id);
  }
  EXPECT_EQ(arm.dispatch_prepared_motion_calls, 0);
  EXPECT_EQ(backend.commands, 0);
  EXPECT_EQ(backend.closes, 0);
  EXPECT_EQ(backend.opens, 0);
}

TEST(ResourceAddressedExecutionKernelOperatorAlarmTest, ContinueCommandFinalAlarmRefusalDuringZeroMovingStopIsDisposed) {
  FakeClock clock;
  ManualScheduler scheduler;
  FinalPneumaticTestBackend backend;
  GripperParticipantEngine output(backend, clock);
  HeldSettlementCall prepare, writer;
  PreparedGripperForwarder forwarder(output, [] {});
  forwarder.prepare_hook = prepare.Blocker();
  FakeOperationJournal journal;
  journal.record_hook = [block = writer.Blocker()](std::string_view kind) {
    if (kind == "state:subordinate_command_prepared") block();
  };
  const ProgramCommandSchemaRefDTO schema{CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto physical = make_binding("gripper", "gripper.target", "tool.gripper.command", CoordinateKind::kLinear, schema);
  auto registration = LogicalGripperRegistration(physical, output);
  registration.prepared_motion_engine = &forwarder;
  auto config = attention_config();
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  ResourceAddressedExecutionKernel kernel({registration}, clock, scheduler, journal, config);
  ASSERT_TRUE(kernel.PublishOperatorAlarmAttention(attention_snapshot(1U)).ok());
  ASSERT_TRUE(claim_program_execution(kernel).ok());
  ASSERT_TRUE(kernel.register_program_run_capture(pneumatic_policy_capture(physical)).ok());
  const auto ready = kernel.get_program_execution_scope(ProgramRunId("run.1"));
  ASSERT_TRUE(ready.ok());
  ASSERT_TRUE(kernel.start_program_selection(program_selection_request("alarm.continue.start", "all"),
      ready.value().selection_revision).ok());
  auto executing = std::async(std::launch::async, [&] {
    return kernel.execute(pneumatic_policy_operation("alarm.continue.command"));
  });
  ASSERT_TRUE(prepare.Entered());
  // Exact source/oracle partial selection: raw Held a_child is effective
  // Continue because its Hold parent's subtree is not wholly held.
  const auto stopped = kernel.stop_program_selection(program_selection_request("alarm.continue.stop", "child_only"));
  ASSERT_TRUE(stopped.ok()) << stopped.error().message;
  prepare.Release();
  ASSERT_TRUE(writer.Entered());
  std::vector<std::string> affected;
  for (const auto& resource : physical.value().resources) affected.push_back(resource.resource_id.value());
  ASSERT_TRUE(kernel.PublishOperatorAlarmAttention(attention_snapshot(2U,
      {alarm_member("late.output", OperatorAlarmAttentionGateDTO::kAcknowledgement, affected)})).ok());
  writer.Release();
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto state = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(state.ok());
  ASSERT_EQ(state.value().participants.size(), 1U);
  EXPECT_TRUE(state.value().active_stop_id);
  EXPECT_EQ(state.value().state, OperationStateKind::kInterventionRequired);
  EXPECT_EQ(state.value().participants.front().state, OperationStateKind::kInterventionRequired);
  ASSERT_TRUE(state.value().participants.front().terminal_error);
  EXPECT_EQ(state.value().participants.front().terminal_error->code, "unacknowledged_operator_alarms");
  for (const auto& slot : kernel.resource_snapshot()) {
    ASSERT_TRUE(slot.owner);
    EXPECT_EQ(slot.state, ResourceSlotState::kTerminal);
    EXPECT_EQ(slot.stop_generation, StopGeneration(0U));
  }
  const auto prepared = output.ObservePreparedCapabilityCommand(1U);
  ASSERT_TRUE(prepared.ok());
  EXPECT_EQ(prepared.value().state, ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
  EXPECT_FALSE(prepared.value().dispatch_result);
  EXPECT_EQ(backend.commands, 0);
  EXPECT_EQ(backend.closes, 0);
  EXPECT_EQ(backend.opens, 0);
}

TEST(ResourceAddressedExecutionKernelTest, FailedMovingStopDisposesLaterExcludedPreparedCommandWithoutSending) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine arm;
  arm.next_stop_result = {false, ErrorDTO{"actual_moving_stop_failed", "Moving hard stop failed", {}}};
  FinalPneumaticTestBackend backend;
  GripperParticipantEngine output(backend, clock);
  HeldSettlementCall first_dispatch;
  arm.execute_return_hook = first_dispatch.Blocker();
  const ProgramCommandSchemaRefDTO schema{CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
      CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
  const auto moving = make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular);
  const auto command = coordinated_occurrence(make_binding("gripper", "gripper.target", "tool.gripper.command",
      CoordinateKind::kLinear, schema), "2");
  ResourceAddressedExecutionKernel kernel({registration(moving, arm), LogicalGripperRegistration(command, output)},
      clock, scheduler, default_journal, {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
  auto executing = std::async(std::launch::async, [&] {
    return kernel.execute(coordinated_motion_command_operation("fault.before.later.command"));
  });
  ASSERT_TRUE(first_dispatch.Entered());
  const auto before = output.ObservePreparedCapabilityCommand(1U);
  ASSERT_TRUE(before.ok());
  ASSERT_EQ(before.value().state, ResolvedPreparedCapabilityCommandStateDTO::kPrepared);
  // Ordinary exhausted Stop is participant-scoped under Q29. The genuine
  // component incident supplies the independent cell-admission closure.
  const auto stopped = kernel.RequestComponentIncidentContainment(
      ComponentIncidentContainmentIntentDTO{"fault.before.later.command.incident",
          moving.value().controllable_component_id, LifecycleBlockingCauseClassDTO::kProviderLost});
  ASSERT_TRUE(stopped.ok());
  ASSERT_TRUE(wait_until([&] {
    return kernel.get_stop_status(stopped.value().stop_id).value().stop_certificate.has_value() &&
           kernel.get_stop_fault_latch().has_value();
  }));
  const auto stop_before_return = kernel.get_stop_status(stopped.value().stop_id).value();
  EXPECT_EQ(backend.commands, 0);
  first_dispatch.Release();
  const auto accepted = executing.get();
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
  const auto after = kernel.get_operation_state(accepted.value().operation_id).value();
  ASSERT_EQ(after.participants.size(), 2U);
  EXPECT_EQ(after.state, OperationStateKind::kInterventionRequired);
  EXPECT_EQ(after.participants.back().state, OperationStateKind::kInterventionRequired);
  ASSERT_TRUE(after.participants.back().terminal_error);
  EXPECT_EQ(after.participants.back().terminal_error->details.at("reason"), "motion_admission_closed");
  const auto cancelled = output.ObservePreparedCapabilityCommand(1U);
  ASSERT_TRUE(cancelled.ok());
  EXPECT_EQ(cancelled.value().state, ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
  EXPECT_FALSE(cancelled.value().dispatch_result);
  for (const auto& slot : kernel.resource_snapshot()) {
    ASSERT_TRUE(slot.owner);
    EXPECT_EQ(slot.state, ResourceSlotState::kTerminal);
    EXPECT_EQ(slot.owner->operation_id, accepted.value().operation_id);
  }
  EXPECT_EQ(kernel.get_stop_status(stopped.value().stop_id).value().stop_certificate,
            stop_before_return.stop_certificate);
  EXPECT_TRUE(kernel.get_stop_fault_latch());
  EXPECT_EQ(backend.commands, 0);
  EXPECT_EQ(backend.closes, 0);
  EXPECT_EQ(backend.opens, 0);
}

// Append inside the existing test translation unit's anonymous namespace.
// Requires only forwarder-local-fixture.patch. This is authored, unexecuted
// Core unit source over the genuine prepared GripperParticipantEngine.
TEST(ResourceAddressedExecutionKernelTest, PreparedCancellationRetryRetainsOwnerUntilActualCancelAndObserveReturn) {
  for (const bool block_observe : {false, true}) {
    SCOPED_TRACE(block_observe);
    FakeClock clock;
    ManualScheduler scheduler;
    FinalPneumaticTestBackend backend;
    GripperParticipantEngine owner(backend, clock);
    HeldSettlementCall before_dispatch, retry_call;
    PreparedGripperForwarder forwarder(owner, before_dispatch.Blocker());
    const ProgramCommandSchemaRefDTO schema{CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
        CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
    const auto physical = make_binding("gripper", "gripper.target", "tool.gripper.command",
        CoordinateKind::kLinear, schema);
    auto row = LogicalGripperRegistration(physical, owner);
    row.prepared_motion_engine = &forwarder;
    ResourceAddressedExecutionKernelConfig config{RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U};
    config.manager_liveness_required_set = EmptyManagerLivenessSet();
    ResourceAddressedExecutionKernel kernel({row}, clock, scheduler, default_journal, config);
    ASSERT_TRUE(claim_program_execution(kernel).ok());
    ASSERT_TRUE(kernel.register_program_run_capture(pneumatic_policy_capture(physical)).ok());
    start_program_motion(kernel);
    const auto original = pneumatic_policy_operation("retry.borrow.original");
    auto executing = std::async(std::launch::async, [&] { return kernel.execute(original); });
    ASSERT_TRUE(before_dispatch.Entered());
    const auto preparation_id = forwarder.last_preparation_id.load();
    ASSERT_NE(preparation_id, 0U);
    const auto held = kernel.stop_program_selection(program_selection_request("retry.borrow.hold", "whole"));
    ASSERT_TRUE(held.ok() && held.value().fresh_containment);
    const auto actual_cancel = owner.ObservePreparedCapabilityCommand(preparation_id);
    ASSERT_TRUE(actual_cancel.ok());
    EXPECT_EQ(actual_cancel.value().state, ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
    EXPECT_FALSE(actual_cancel.value().dispatch_result);
    forwarder.observation_unavailable = true;
    before_dispatch.Release();
    const auto accepted = executing.get();
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    ASSERT_TRUE(wait_until([&] {
      const auto stop = kernel.get_stop_status(held.value().fresh_containment->stop_id);
      return stop.ok() && stop.value().stop_certificate.has_value();
    }));
    ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
    const auto unknown = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(unknown.ok() && unknown.value().resident);
    EXPECT_NE(unknown.value().operation.state, OperationStateKind::kCancelledPreDispatch);
    EXPECT_NE(unknown.value().operation.state, OperationStateKind::kCompleted);
    const auto original_slots = kernel.resource_snapshot();
    ASSERT_EQ(original_slots.size(), 1U);
    ASSERT_TRUE(original_slots.front().owner);
    EXPECT_NE(original_slots.front().state, ResourceSlotState::kFree);

    // Only an actual retry owner call is held, never a manufactured Kernel
    // borrow. The same returned preparation ID reaches the real owner.
    forwarder.observation_unavailable = false;
    if (block_observe) forwarder.observe_hook = retry_call.Blocker();
    else forwarder.cancel_hook = retry_call.Blocker();
    auto retrying = std::async(std::launch::async, [&] { return kernel.reconcile_subordinate_state(); });
    ASSERT_TRUE(retry_call.Entered());
    const auto during = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(during.ok() && during.value().resident);
    const auto concurrent_request = control_request("retry.borrow.concurrent.reset", accepted.value(),
        during.value().operation.operation_revision.value());
    auto resetting = std::async(std::launch::async, [&] { return kernel.reset(concurrent_request); });
    // Cancel is outside the proof writer; Observe may hold that writer, so
    // Reset may remain pending until the actual Observe call returns.
    if (!block_observe) {
      EXPECT_EQ(resetting.wait_for(std::chrono::seconds(10)), std::future_status::ready);
    }
    std::optional<Result<OperationControlAcceptedDTO>> early_reset;
    if (resetting.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
      early_reset.emplace(resetting.get());
      ASSERT_FALSE(early_reset->ok());
      EXPECT_EQ(early_reset->error().details.at("reason"), "operation_effect_in_flight");
    }
    const auto retained = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(retained.ok() && retained.value().resident);
    const auto borrowed_slots = kernel.resource_snapshot();
    ASSERT_EQ(borrowed_slots.size(), 1U);
    EXPECT_EQ(borrowed_slots.front().owner, original_slots.front().owner);
    EXPECT_EQ(borrowed_slots.front().state, original_slots.front().state);
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.closes, 0);
    EXPECT_EQ(backend.opens, 0);

    retry_call.Release();
    ASSERT_TRUE(retrying.get().ok());
    if (!early_reset) early_reset.emplace(resetting.get());
    const auto permanent = owner.ObservePreparedCapabilityCommand(preparation_id);
    ASSERT_TRUE(permanent.ok());
    EXPECT_EQ(permanent.value().state, ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
    EXPECT_FALSE(permanent.value().dispatch_result);
    const auto after_return = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(after_return.ok());
    if (after_return.value().resident) {
      // A concurrent refusal/stale CAS retains the exact owner. Only now,
      // after the real call and positive proof, may local retirement occur.
      ASSERT_EQ(after_return.value().operation.state, OperationStateKind::kCancelledPreDispatch);
      const auto cleanup = kernel.reset(control_request("retry.borrow.local.retirement", accepted.value(),
          after_return.value().operation.operation_revision.value()));
      ASSERT_TRUE(cleanup.ok()) << cleanup.error().message;
    } else {
      // Writer-serialized Reset may complete only after Observe returned.
      ASSERT_TRUE(early_reset->ok());
      ASSERT_TRUE(after_return.value().last_control);
      EXPECT_EQ(after_return.value().last_control->request_id, concurrent_request.request_context.request_id);
    }
    const auto history = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(history.ok());
    EXPECT_FALSE(history.value().resident);
    EXPECT_FALSE(history.value().control_pending);
    for (const auto& slot : kernel.resource_snapshot()) {
      EXPECT_EQ(slot.state, ResourceSlotState::kFree);
      EXPECT_FALSE(slot.owner);
    }
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.closes, 0);
    EXPECT_EQ(backend.opens, 0);
  }
}

// Append inside the existing anonymous namespace, after the typed pneumatic
// fixtures. Uses forwarder-local-fixture.patch only to capture actual Prepare ID.
// This reachable unscoped/F2-fault case has historical release=false for the
// pneumatic row. It does NOT claim the publicly unreachable scoped mixed
// CommonStart/historical-release=true case described in limitations.md.
TEST(ResourceAddressedExecutionKernelTest, MixedResetRetainsUnknownOrdinaryPreparationAndSkipsProvenNoEffectOwner) {
  for (const bool initially_unknown : {false, true}) {
    SCOPED_TRACE(initially_unknown);
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine arm;
    arm.next_stop_result = StopResultDTO{false,
        ErrorDTO{"actual_moving_stop_failed", "Actual moving provider refuses containment", {}}};
    FinalPneumaticTestBackend backend;
    GripperParticipantEngine owner(backend, clock);
    HeldSettlementCall first_dispatch, moving_reset;
    arm.execute_return_hook = first_dispatch.Blocker();
    PreparedGripperForwarder forwarder(owner, [] {});
    const ProgramCommandSchemaRefDTO schema{CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
        CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
    const auto moving = make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular);
    const auto physical = coordinated_occurrence(make_binding("gripper", "gripper.target", "tool.gripper.command",
        CoordinateKind::kLinear, schema), "2");
    auto ordinary = LogicalGripperRegistration(physical, owner);
    ordinary.prepared_motion_engine = &forwarder;
    ResourceAddressedExecutionKernel kernel({registration(moving, arm), ordinary}, clock, scheduler,
        default_journal, {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
    auto executing = std::async(std::launch::async, [&] {
      return kernel.execute(coordinated_motion_command_operation("mixed.reset.actual.fault"));
    });
    ASSERT_TRUE(first_dispatch.Entered());
    const auto preparation_id = forwarder.last_preparation_id.load();
    ASSERT_NE(preparation_id, 0U);
    const auto prepared = owner.ObservePreparedCapabilityCommand(preparation_id);
    ASSERT_TRUE(prepared.ok());
    ASSERT_EQ(prepared.value().state, ResolvedPreparedCapabilityCommandStateDTO::kPrepared);
    ASSERT_FALSE(prepared.value().dispatch_result);
    const auto stopped = kernel.RequestComponentIncidentContainment(
        ComponentIncidentContainmentIntentDTO{"mixed.reset.actual.incident",
            moving.value().controllable_component_id, LifecycleBlockingCauseClassDTO::kProviderLost});
    ASSERT_TRUE(stopped.ok());
    // The actual component incident closes admission. An ordinary failed
    // software-hard stage alone does not latch the cell under preserved Q29.
    ASSERT_TRUE(wait_until([&] {
      const auto stop = kernel.get_stop_status(stopped.value().stop_id);
      return stop.ok() && stop.value().stop_certificate.has_value() && kernel.get_stop_fault_latch().has_value();
    }));
    forwarder.observation_unavailable = initially_unknown;
    first_dispatch.Release();
    const auto accepted = executing.get();
    ASSERT_TRUE(accepted.ok()) << accepted.error().message;
    ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
    const auto actual_cancel = owner.ObservePreparedCapabilityCommand(preparation_id);
    ASSERT_TRUE(actual_cancel.ok());
    EXPECT_EQ(actual_cancel.value().state, ResolvedPreparedCapabilityCommandStateDTO::kCancelledPreDispatch);
    EXPECT_FALSE(actual_cancel.value().dispatch_result);
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.closes, 0);
    EXPECT_EQ(backend.opens, 0);
    const auto original = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(original.ok() && original.value().resident);
    if (initially_unknown) {
      const auto refused = kernel.reset(control_request("mixed.reset.unknown", accepted.value(),
          original.value().operation.operation_revision.value()));
      ASSERT_FALSE(refused.ok());
      EXPECT_EQ(refused.error().details.at("reason"), "operation_effect_in_flight");
      EXPECT_EQ(arm.certified_reset_calls, 0);
      EXPECT_TRUE(kernel.get_operation_projection(accepted.value().operation_id).value().resident);
      for (const auto& slot : kernel.resource_snapshot()) {
        ASSERT_TRUE(slot.owner);
        EXPECT_EQ(slot.owner->operation_id, accepted.value().operation_id);
        EXPECT_NE(slot.state, ResourceSlotState::kFree);
      }
      forwarder.observation_unavailable = false;
      ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
    }
    const auto proven = kernel.get_operation_projection(accepted.value().operation_id);
    ASSERT_TRUE(proven.ok() && proven.value().resident);
    ASSERT_EQ(proven.value().operation.participants.size(), 2U);
    // The original moving fault and ordinary final refusal are truthful
    // terminal causes, not fake errors added to make aggregate reduction work.
    EXPECT_EQ(proven.value().operation.state, OperationStateKind::kInterventionRequired);
    const auto& ordinary_row = proven.value().operation.participants.back();
    EXPECT_EQ(ordinary_row.payload_kind, OperationParticipantPayloadKind::kCapabilityCommand);
    EXPECT_EQ(ordinary_row.state, OperationStateKind::kInterventionRequired);
    ASSERT_TRUE(ordinary_row.terminal_error);
    EXPECT_EQ(ordinary_row.terminal_error->details.at("reason"), "motion_admission_closed");

    // Restore only the real unit provider's next containment outcome for the
    // explicit user Reset. Kernel faults and admission remain owner-controlled.
    arm.next_stop_result = StopResultDTO{true, std::nullopt};
    arm.reset_effect_hook = moving_reset.Blocker();
    const auto request = control_request("mixed.reset.proven", accepted.value(),
        proven.value().operation.operation_revision.value());
    auto resetting = std::async(std::launch::async, [&] { return kernel.reset(request); });
    ASSERT_TRUE(moving_reset.Entered());
    EXPECT_TRUE(kernel.get_operation_projection(accepted.value().operation_id).value().resident);
    for (const auto& slot : kernel.resource_snapshot()) {
      ASSERT_TRUE(slot.owner);
      EXPECT_EQ(slot.owner->operation_id, accepted.value().operation_id);
      EXPECT_NE(slot.state, ResourceSlotState::kFree);
    }
    EXPECT_EQ(arm.certified_reset_calls, 1);
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.closes, 0);
    EXPECT_EQ(backend.opens, 0);
    moving_reset.Release();
    const auto reset = resetting.get();
    ASSERT_TRUE(reset.ok()) << reset.error().message;
    ASSERT_TRUE(wait_until([&] {
      const auto history = kernel.get_operation_projection(accepted.value().operation_id);
      return history.ok() && !history.value().resident && !history.value().control_pending;
    }));
    for (const auto& slot : kernel.resource_snapshot()) {
      EXPECT_EQ(slot.state, ResourceSlotState::kFree);
      EXPECT_FALSE(slot.owner);
    }
    EXPECT_EQ(arm.certified_reset_calls, 1);
    EXPECT_EQ(backend.commands, 0);
    EXPECT_EQ(backend.closes, 0);  // No pneumatic Reset invalidation.
    EXPECT_EQ(backend.opens, 0);   // No pneumatic authorization.
  }
}


TEST(ResourceAddressedExecutionKernelTest, OrdinaryPneumaticAckRetiresOnceAcrossStopOrderingAndRealReturn) {
  for (const bool stop_first : {false, true}) {
    for (const bool hold_acceptance : {false, true}) {
      SCOPED_TRACE(stop_first);
      SCOPED_TRACE(hold_acceptance);
      FakeClock clock;
      ManualScheduler scheduler;
      FakeOperationJournal journal;
      FinalPneumaticTestBackend backend;
      GripperParticipantEngine owner(backend, clock);
      const ProgramCommandSchemaRefDTO schema{CommandSchemaId(std::string(kGripperPositionCommandSchemaId)),
          CommandSchemaRevision(std::string(kGripperPositionCommandSchemaRevision))};
      const auto physical = make_binding("gripper", "gripper.target", "tool.gripper.command", CoordinateKind::kLinear, schema);
      ResourceAddressedExecutionKernel kernel({LogicalGripperRegistration(physical, owner)}, clock, scheduler,
          journal, {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
      const auto accepted = kernel.execute(command_operation("ordinary.ack.stop.ordering"));
      ASSERT_TRUE(accepted.ok()) << accepted.error().message;
      EXPECT_EQ(backend.commands, 1);
      const auto stop = [&] {
        const auto stopped = kernel.full_stop({{RequestId("ordinary.ack.stop"), RequestOwnerEpoch("kernel.epoch.1"),
            "test", {}}, StopGeneration(0U), {}});
        EXPECT_TRUE(stopped.ok());
        if (stopped.ok()) {
          EXPECT_TRUE(wait_until([&] {
            return kernel.get_stop_status(stopped.value().stop_id).value().stop_certificate.has_value();
          }));
          const auto status = kernel.get_stop_status(stopped.value().stop_id);
          EXPECT_TRUE(status.ok());
          if (status.ok()) {
            EXPECT_TRUE(status.value().scope_entries.empty());
            EXPECT_TRUE(status.value().attempted_stage_results.empty());
          }
        }
      };
      if (stop_first) stop();
      backend.finish(false);
      ASSERT_TRUE(kernel.reconcile_subordinate_state().ok());
      const auto completed = kernel.get_operation_projection(accepted.value().operation_id);
      ASSERT_TRUE(completed.ok() && completed.value().resident);
      ASSERT_EQ(completed.value().operation.state, OperationStateKind::kCompleted);
      HeldSettlementCall ack_return;
      std::atomic<int> actual_ack_reads{};
      backend.status_read_hook = [&, block = ack_return.Blocker()] {
        ++actual_ack_reads;
        if (!hold_acceptance) block();
      };
      if (hold_acceptance) journal.control_acceptance_hook = ack_return.Blocker();
      const auto request = control_request("ordinary.ack.once", accepted.value(),
          completed.value().operation.operation_revision.value());
      auto acknowledging = std::async(std::launch::async, [&] { return kernel.acknowledge_completed(request); });
      ASSERT_TRUE(ack_return.Entered());
      if (!stop_first) stop();
      const auto borrowed = kernel.get_operation_projection(accepted.value().operation_id);
      ASSERT_TRUE(borrowed.ok() && borrowed.value().resident);
      EXPECT_TRUE(borrowed.value().control_pending);
      for (const auto& row : kernel.resource_snapshot()) {
        ASSERT_TRUE(row.owner);
        EXPECT_EQ(row.owner->operation_id, accepted.value().operation_id);
        EXPECT_EQ(row.state, ResourceSlotState::kTerminal);
      }
      EXPECT_EQ(backend.commands, 1);
      EXPECT_EQ(backend.opens, 0);
      EXPECT_EQ(backend.closes, 0);
      // Actual ordinary result consumption or its durable acceptance is
      // still held. Neither Stop order releases this exact owner early.
      ack_return.Release();
      const auto acknowledged = acknowledging.get();
      ASSERT_TRUE(acknowledged.ok()) << acknowledged.error().message;
      ASSERT_TRUE(wait_until([&] {
        const auto history = kernel.get_operation_projection(accepted.value().operation_id);
        return history.ok() && !history.value().resident && !history.value().control_pending;
      }));
      const auto history = kernel.get_operation_projection(accepted.value().operation_id);
      ASSERT_TRUE(history.ok() && history.value().last_control);
      EXPECT_EQ(history.value().operation.state, OperationStateKind::kCompleted);
      EXPECT_EQ(history.value().last_control->request_id, request.request_context.request_id);
      const auto replay = kernel.acknowledge_completed(request);
      ASSERT_TRUE(replay.ok());
      EXPECT_EQ(replay.value().replay_status, RequestReplayStatusDTO::kReplayedExact);
      EXPECT_EQ(replay.value().operation_revision_after_acceptance,
                acknowledged.value().operation_revision_after_acceptance);
      EXPECT_EQ(actual_ack_reads, 1);
      {
        std::lock_guard lock(journal.mutex);
        EXPECT_EQ(std::count(journal.calls.begin(), journal.calls.end(), "control_accepted"), 1);
      }
      for (const auto& row : kernel.resource_snapshot()) {
        EXPECT_EQ(row.state, ResourceSlotState::kFree);
        EXPECT_FALSE(row.owner);
      }
      EXPECT_EQ(backend.commands, 1);
      EXPECT_EQ(backend.opens, 0);
      EXPECT_EQ(backend.closes, 0);
    }
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     AuthoredScopeIsCapturedBeforeDispatchAndReplayExact) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.defer_prepare_completion = true;
  ResourceAddressedExecutionKernelConfig config{RequestOwnerEpoch("kernel.epoch.1"),
                                                CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  ResourceAddressedExecutionKernel kernel(
      {registration(
          make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal, std::move(config));
  ASSERT_TRUE(claim_program_execution(kernel).ok());
  auto capture = program_execution_capture();
  auto table = std::make_shared<ProgramExecutionTableDTO>(*capture.table);
  capture.table = table;
  ASSERT_TRUE(kernel.register_program_run_capture(capture).ok());
  start_program_motion(kernel);
  auto intent = scoped_motion_operation("retry.context.accepted");
  const auto accepted = kernel.execute(intent);
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto state = kernel.get_operation_state(accepted.value().operation_id);
  ASSERT_TRUE(state.ok());
  EXPECT_EQ(state.value().participants.front().execution_scope,
            intent.participants.front().execution_scope);
  EXPECT_EQ(engine.execute_calls, 0);
  const auto replay = kernel.execute(intent);
  ASSERT_TRUE(replay.ok());
  EXPECT_EQ(replay.value().replay_status, RequestReplayStatusDTO::kReplayedExact);
  intent.participants.front().execution_scope->node_attempt_id = "attempt.changed";
  const auto conflicting = kernel.execute(intent);
  ASSERT_FALSE(conflicting.ok());
  EXPECT_EQ(conflicting.error().details.at("reason"), "request_id_conflict");
  intent.participants.front().execution_scope.reset();
  EXPECT_FALSE(kernel.execute(intent).ok());
}

TEST(ResourceAddressedExecutionKernelTest,
     RunnerLossRequiresExactManagerAndHeldRunBeforeFirstCapture) {
  for (const auto scenario : {0, 1, 2, 3, 4}) {
    SCOPED_TRACE(scenario);
    FakeClock clock;
    ManualScheduler scheduler;
    FakeParticipantEngine engine;
    FakeOperationJournal journal;
    ResourceAddressedExecutionKernelConfig config{RequestOwnerEpoch("kernel.epoch.1"),
                                                  CellId("cell.test"), 8U};
    config.manager_liveness_required_set = EmptyManagerLivenessSet();
    ResourceAddressedExecutionKernel kernel(
        {registration(
            make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
            engine)},
        clock, scheduler, journal, std::move(config));
    ASSERT_TRUE(claim_program_execution(kernel).ok());
    ASSERT_TRUE(kernel.register_program_run_capture(program_execution_capture()).ok());
    ProgramRunnerContactLossDTO loss{
        RequestOwnerEpoch("manager.owner.1"),
        RuntimeEpoch("manager.epoch.1"),
        {RequestOwnerEpoch("program.owner"), 2U, ProgramCycleStateDTO::kRunning,
         ProgramRunId("run.1"), CellAdmissionClaimGeneration(1U), std::nullopt},
        "program_runner_liveness_probe",
        "connection refused"};
    if (scenario == 0) loss.manager_owner_epoch = RequestOwnerEpoch("foreign.manager");
    if (scenario == 1)
      loss.established_cycle.program_runner_owner_epoch = RequestOwnerEpoch("foreign.runner");
    if (scenario == 2) loss.established_cycle.program_run_id = ProgramRunId("other.run");
    if (scenario == 3)
      loss.established_cycle.cycle_claim_generation = CellAdmissionClaimGeneration(9U);
    CellAdmissionReadinessSnapshotDTO closed{
        false, loss.established_cycle, false, 1U, 0U, false, false, 0U, 0U, 0U};
    closed.program_runner_loss = loss;
    if (scenario == 4) journal.fail_next_kind = "cell_admission_generation_advanced";
    const auto result = kernel.UpdateCellAdmissionReadiness(closed);
    EXPECT_FALSE(result.ok());
    EXPECT_EQ(kernel.get_program_runner_loss(),
              scenario == 4 ? std::optional<ProgramRunnerContactLossDTO>(loss) : std::nullopt);
    EXPECT_EQ(engine.prepare_motion_calls, 0);
    EXPECT_EQ(engine.execute_calls, 0);
  }
}

TEST(ResourceAddressedExecutionKernelTest,
     RunnerLossRemainsFirstAndMatchingReplaySurvivesClaimRetirement) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  FakeOperationJournal journal;
  ResourceAddressedExecutionKernelConfig config{RequestOwnerEpoch("kernel.epoch.1"),
                                                CellId("cell.test"), 8U};
  config.manager_liveness_required_set = EmptyManagerLivenessSet();
  config.cell_admission_settlement_validator = [](const auto&, const auto&) {
    return Result<void>::Ok();
  };
  ResourceAddressedExecutionKernel kernel(
      {registration(
          make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, journal, std::move(config));
  const auto acquired = claim_program_execution(kernel);
  ASSERT_TRUE(acquired.ok());
  ASSERT_TRUE(kernel.register_program_run_capture(program_execution_capture()).ok());
  ProgramRunnerContactLossDTO loss{
      RequestOwnerEpoch("manager.owner.1"),
      RuntimeEpoch("manager.epoch.1"),
      {RequestOwnerEpoch("program.owner"), 2U, ProgramCycleStateDTO::kRunning,
       ProgramRunId("run.1"), acquired.value().claim_generation, std::nullopt},
      "program_runner_liveness_probe",
      "connection refused"};
  CellAdmissionReadinessSnapshotDTO closed{
      false, loss.established_cycle, false, 1U, 0U, false, false, 0U, 0U, 0U};
  closed.program_runner_loss = loss;
  ASSERT_TRUE(kernel.UpdateCellAdmissionReadiness(closed).ok());
  const auto& claim = acquired.value();
  ASSERT_TRUE(kernel
                  .ReleaseCellAdmissionClaim({claim.intent.owner_role,
                                              claim.intent.owner_epoch,
                                              claim.intent.owner_transaction_id,
                                              claim.intent.request_id,
                                              claim.intent.request_payload_digest,
                                              claim.acquired_admission_generation,
                                              claim.claim_generation,
                                              {CellAdmissionSettlementKindDTO::kExplicitReset,
                                               ContentDigest(test_digest('b'))}})
                  .ok());
  ASSERT_FALSE(kernel.ReadHeldCellAdmissionClaim(CellAdmissionClaimKindDTO::kProgramCycle));
  EXPECT_TRUE(kernel.UpdateCellAdmissionReadiness(closed).ok());
  closed.program_runner_loss.reset();
  EXPECT_TRUE(kernel.UpdateCellAdmissionReadiness(closed).ok());
  EXPECT_EQ(kernel.get_program_runner_loss(), loss);
  closed.program_runner_loss = loss;
  closed.program_runner_loss->message = "another failure";
  EXPECT_FALSE(kernel.UpdateCellAdmissionReadiness(closed).ok());
  EXPECT_EQ(kernel.get_program_runner_loss(), loss);
}

TEST(ResourceAddressedExecutionKernelTest,
     GeneralCloseRetiresNonRetryableNoEffectFailureAndReplays) {
  FakeClock clock;
  ManualScheduler scheduler;
  FakeParticipantEngine engine;
  engine.prepare_call_failure =
      ErrorDTO{"request_refused", "non-retryable preparation failure", {}};
  ResourceAddressedExecutionKernel kernel(
      {registration(
          make_binding("arm", "arm", "execution.trajectory.execute", CoordinateKind::kAngular),
          engine)},
      clock, scheduler, default_journal,
      {RequestOwnerEpoch("kernel.epoch.1"), CellId("cell.test"), 8U});
  const auto accepted = kernel.execute(motion_operation("close.no_effect"));
  ASSERT_TRUE(accepted.ok()) << accepted.error().message;
  const auto projection = kernel.get_operation_recovery_assessment(accepted.value().operation_id);
  ASSERT_TRUE(projection.ok()) << projection.error().message;
  const auto& assessment = projection.value().assessment;
  ASSERT_TRUE(assessment.eligible_close);
  EXPECT_FALSE(assessment.retry_eligibility.eligible);
  KernelRecoveryActionRequestDTO request{"close.request",
                                         RecoveryAction::kCloseOperation,
                                         "program_runner",
                                         assessment.assessment_revision,
                                         assessment.control_command_epoch,
                                         assessment.execution_id,
                                         assessment.latch_id,
                                         assessment.stop_certificate_id,
                                         assessment.stop_owner_generation,
                                         "failure leaving node",
                                         false};
  auto stale = request;
  ++stale.expected_control_command_epoch;
  EXPECT_FALSE(kernel
                   .apply_operation_recovery_action(accepted.value().operation_id,
                                                    projection.value().operation_revision, stale)
                   .ok());
  auto fresh = request;
  fresh.fresh_motion_attempt = true;
  EXPECT_FALSE(kernel
                   .apply_operation_recovery_action(accepted.value().operation_id,
                                                    projection.value().operation_revision, fresh)
                   .ok());
  const auto closed = kernel.apply_operation_recovery_action(
      accepted.value().operation_id, projection.value().operation_revision, request);
  ASSERT_TRUE(closed.ok()) << closed.error().message;
  ASSERT_TRUE(closed.value().accepted);
  const auto history = kernel.get_operation_projection(accepted.value().operation_id);
  ASSERT_TRUE(history.ok());
  EXPECT_FALSE(history.value().resident);
  ASSERT_TRUE(history.value().operation.participants.front().terminal_error);
  EXPECT_EQ(history.value().operation.participants.front().terminal_error->code, "request_refused");
  for (const auto& slot : kernel.resource_snapshot()) {
    EXPECT_EQ(slot.state, ResourceSlotState::kFree);
    EXPECT_FALSE(slot.owner);
  }
  const auto replay = kernel.apply_operation_recovery_action(
      accepted.value().operation_id, projection.value().operation_revision, request);
  ASSERT_TRUE(replay.ok());
  EXPECT_TRUE(replay.value().accepted);
  auto conflict = request;
  conflict.principal_id = "different_owner";
  const auto refused = kernel.apply_operation_recovery_action(
      accepted.value().operation_id, projection.value().operation_revision, conflict);
  ASSERT_FALSE(refused.ok());
  EXPECT_EQ(refused.error().code, "invalid_request");
  EXPECT_EQ(refused.error().details.at("reason"), "request_id_conflict");
  EXPECT_EQ(engine.recovery_action_calls, 0);
  EXPECT_EQ(engine.certified_reset_calls, 0);
  EXPECT_EQ(engine.execute_calls, 0);
}

